@if($import && $import->error_count)<script>const importErrors=@json($import->report['errors']??[]);document.querySelector('[data-error-download]')?.addEventListener('click',()=>{const rows=[['row','column','message'],...importErrors.map(x=>[x.row,x.column,x.message])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='student-import-errors.csv';a.click();URL.revokeObjectURL(a.href)})</script>@endif
@if(!$import)<script>document.querySelectorAll('[data-copy-class]').forEach(button=>button.addEventListener('click',async()=>{await navigator.clipboard.writeText(`${button.dataset.copyClass},${button.dataset.copyArm}`);button.textContent='Copied'}))</script>@endif
